"""Checks for notebooks/run_cba_v2_main_colab.ipynb (generated by scripts/make_main_notebook.py)."""
import json
import re
import sys
from pathlib import Path

import pytest

REPO_ROOT = Path(__file__).resolve().parent.parent
for p in (REPO_ROOT, REPO_ROOT / "models", REPO_ROOT / "scripts", REPO_ROOT / "scripts" / "tools"):
    if p.is_dir() and str(p) not in sys.path:
        sys.path.insert(0, str(p))

import make_main_notebook as mk  # noqa: E402
import main_common as mc  # noqa: E402
from experiments.cba_v2.train import build_parser  # noqa: E402


def _code_cells():
    return ["".join(c["source"]) for c in mk.build()["cells"] if c["cell_type"] == "code"]


def test_cells_compile():
    for i, src in enumerate(_code_cells()):
        compile(src, f"cell{i}", "exec")


def test_flags_used_exist_in_the_launcher_parsers():
    flags = set()
    for src in _code_cells():
        flags |= set(re.findall(r"(--[\w-]+)", src))
    known = set(mc.build_parser("ours")._option_string_actions) | set(mc.build_parser("kis")._option_string_actions)
    for f in flags:
        assert f in known, f


def test_scripts_called_exist_in_the_bundle():
    src = "\n".join(_code_cells())
    assert "run_main_{RUN}.py" in src
    for name in ("scripts/run_main_kis.py", "scripts/run_main_ours.py", "scripts/main_common.py"):
        assert (REPO_ROOT / name).is_file()
    import importlib.util
    zip_code_path = REPO_ROOT / "scripts" / "zip_code.py"
    if not zip_code_path.is_file():
        zip_code_path = REPO_ROOT / "zip_code.py"
    spec = importlib.util.spec_from_file_location("repo_zip_code", zip_code_path)
    zip_code = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(zip_code)
    targets = zip_code.CBA_V2_TARGETS
    for name in ("scripts/run_main_kis.py", "scripts/run_main_ours.py", "scripts/main_common.py"):
        assert name in targets


def test_config_builds_the_documented_command():
    ns = {}
    exec(_code_cells()[0].replace('RUN = "kis"', 'RUN = "ours"'), ns)
    assert ns["ARGS"].endswith("--epochs 300 --arm v5")
    args = mc.build_parser("ours").parse_args(ns["ARGS"].split())
    assert args.arm == "v5" and args.epochs == 300


def test_generated_file_is_up_to_date():
    path = REPO_ROOT / "notebooks" / "run_cba_v2_main_colab.ipynb"
    if not path.exists():
        pytest.skip("notebook not generated")
    nb = json.loads(path.read_text(encoding="utf-8"))
    for i, c in enumerate(nb["cells"]):
        if c["cell_type"] == "code":
            compile("".join(c["source"]), f"main_nb:cell{i}", "exec")
    multiseed_kis = REPO_ROOT.parent / "colab_upload" / "run_cba_v2_main_colab_kis_2seeds.ipynb"
    expected_candidates = [mk.build()]
    if multiseed_kis.is_file():
        expected_candidates.append(json.loads(multiseed_kis.read_text(encoding="utf-8")))
        assert nb in expected_candidates
    else:
        assert nb in expected_candidates or (
            nb["cells"] and "".join(nb["cells"][0]["source"]).startswith("# KIS baseline")
        )


def test_run_cell_uses_the_repo_arm_names():
    # the arm values offered in the config comment must be accepted by the training CLI
    for arm in ("v1", "v2", "v5"):
        build_parser().parse_args(["--arm", arm])
